+import { useQuery } from "@tanstack/react-query";
+import { useActiveTradingAddress } from "@/features/accounts";
+import { useActivePerpsProvider } from "@/features/perpetuals/infra";
+import { PerpsProviderRegistry } from "@/features/perpetuals/infra/PerpsProviderRegistry";
+import {
+  type FeeNotionalInput,
+  getFeeNotional,
+} from "@/features/perpetuals/order/utils/fee-notional";
+
+export function useFeeQuote(input: FeeNotionalInput & { symbol: string }) {
+  const provider = useActivePerpsProvider();
+  const { address } = useActiveTradingAddress();
+  const notional = getFeeNotional(input);
+  const network = PerpsProviderRegistry.getHyperliquidNetwork();
+
+  return useQuery({
+    queryKey: [
+      "perps-fees",
+      provider.protocolId,
+      network,
+      address?.toLowerCase(),
+      input.symbol,
+      input.orderType,
+      notional,
+    ],
+    queryFn: () =>
+      provider.calculateFees({
+        symbol: input.symbol,
+        orderType: input.orderType,
+        amount: String(notional),
+      }),
+    enabled: Boolean(input.symbol) && notional > 0,
+    staleTime: 0,
+    refetchInterval: 30_000,
+  });
